const $=id=>document.getElementById(id),key='peroxide-lab-v1';
function initialRows(){return [{time:0,vol:0},...Array.from({length:5},()=>({time:'',vol:''}))];}
let state={rows:initialRows(),sample:false},result=null,plotType='concentration';
const ids=['mode','c0','pressure','v1','v2','input','unit','temp','wet'];
function settings(){return {mode:$('mode').value,c0:$('c0').value,pressure:+$('pressure').value,volume:+$('v1').value + +$('v2').value,input:$('input').value,unit:$('unit').value,temp:$('temp').value,wet:$('wet').checked};}
function persist(){try{let config={};ids.forEach(id=>config[id]=id==='wet'?$(id).checked:$(id).value);localStorage.setItem(key,JSON.stringify({...state,config}));$('save').textContent='この端末に保存済み';}catch{$('save').textContent='自動保存できません。CSVをご利用ください';}}
function fmt(v,n=4){return v===null||v===undefined||!Number.isFinite(v)?'—':Math.abs(v)>0&&Math.abs(v)<0.0001?v.toExponential(3):v.toFixed(n);}
function renderRows(){let tbody=$('rows');tbody.replaceChildren();state.rows.forEach((r,i)=>{let tr=document.createElement('tr'),index=document.createElement('td');index.textContent=i===0?'初期':String(i).padStart(2,'0');tr.append(index);['time','vol'].forEach((k,j)=>{let td=document.createElement('td'),input=document.createElement('input');input.type='number';input.step='any';input.min=0;input.value=r[k];if(i===0&&k==='time'){input.readOnly=true;input.setAttribute('aria-label','初期時刻 0');}input.placeholder='—';input.setAttribute('aria-label',`${i+1}行目 ${['時間','捕集体積'][j]}`);input.addEventListener('input',()=>{state.rows[i][k]=input.value;state.sample=false;update();});td.append(input);tr.append(td);});let out=document.createElement('td');out.id='c-'+i;out.textContent='—';tr.append(out);let td=document.createElement('td'),del=document.createElement('button');del.textContent='×';if(i===0)del.disabled=true;del.setAttribute('aria-label',`${i+1}行目を削除`);del.onclick=()=>{state.rows.splice(i,1);state.sample=false;renderRows();update();};td.append(del);tr.append(td);tbody.append(tr);});}
function update(){let c=settings();$('known').hidden=c.mode!=='known';$('liquid').textContent=fmt(c.volume,2)+' mL';$('timehead').textContent=`時間（${c.unit}）`;$('volhead').textContent=(c.input==='total'?'累積体積':'区間の増加体積')+'（mL）';$('samplelabel').hidden=!state.sample;
 let error='',warnings=[];result=null;state.rows.forEach((_,i)=>{$('c-'+i).textContent='—';});
 try{if($('v1').value===''||$('v2').value===''||+$('v1').value<0||+$('v2').value<0)throw Error('反応液の各体積を0以上の数で入力してください。');result=Chem.calculate(state.rows,c);let nonempty=state.rows.map((r,i)=>({r,i})).filter(({r})=>r.time!==''||r.vol!=='');result.data.forEach((r,j)=>{$('c-'+nonempty[j].i).textContent=fmt(r.c);});if(result.data.length&&result.c0===null)warnings.push('初濃度を推定できません。3区間以上の測定と、時間とともに低下する速度が必要です。初濃度が分かる場合は直接入力してください。');if(result.data.some(r=>r.c!==null&&r.c<0))warnings.push('負の濃度が計算されました。初濃度・反応液量・体積の単位・推定方法を確認してください。');if(c.mode==='estimate'&&result.fit&&result.fit.r2<.9)warnings.push('一次反応の回帰との一致が弱いため、推定濃度の解釈に注意してください。');}catch(e){error=e.message;}
 $('count').textContent=(result?.data.length??0)+' 点';$('message').textContent=error||warnings.join(' ')||(result?.data.length?(c.mode==='estimate'?'計算済み。表示濃度は一次反応を仮定した推定値です。':'計算済み。入力した初濃度から各時刻の濃度を求めました。'):'測定値を入力すると、自動で解析します。');$('message').className='message'+(error||warnings.length?' error':'');let f=result?.fit;$('fittext').textContent=f?`回帰結果：k = ${fmt(f.k,6)} s⁻¹、b = ${fmt(f.b,6)} mol/(L·s)。${f.k>0?'推定 C₀ = '+fmt(f.c0)+' mol/L。':'正の速度定数が得られないため推定できません。'}`:'回帰には3区間以上の有効な測定が必要です。';draw();persist();}
function draw(){let p=[],rate=plotType==='rate';if(result?.c0!==null&&result?.c0!==undefined&&result.data.length)p=rate?result.data.filter(r=>r.rate!==null).map(r=>[r.avg,r.rate]):[...(result.data[0]?.t===0?[]:[[0,result.c0]]),...result.data.map(r=>[r.t,r.c])];$('plotnote').textContent=rate?'各点は測定区間の平均濃度とH₂O₂の平均減少速度です。横軸：mol/L、縦軸：mol/(L·s)。':'各測定時刻の濃度を表示します。横軸：時間（s）、縦軸：H₂O₂濃度（mol/L）。';if(!p.length){$('plot').innerHTML='<div class="empty">'+(result?.data.length?'濃度の計算に必要な条件を確認してください。':'測定を記録すると、ここに変化が見えます。')+'<br><small>「練習データを入れる」からも試せます</small></div>';return;}
 let W=750,H=280,L=80,B=42,T=20,RR=25;let xmin=Math.min(0,...p.map(p=>p[0])),xmax=Math.max(...p.map(p=>p[0]))||1,ymin=Math.min(0,...p.map(p=>p[1])),ymax=Math.max(...p.map(p=>p[1]))||1;xmax+=Math.abs(xmax-xmin)*.06;ymax+=Math.abs(ymax-ymin)*.12;let x=v=>L+(v-xmin)/(xmax-xmin)*(W-L-RR),y=v=>H-B-(v-ymin)/(ymax-ymin)*(H-T-B),label=v=>Math.abs(v)>0&&Math.abs(v)<.001?v.toExponential(1):String(+v.toPrecision(3));let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${rate?'濃度と平均速度':'時間と過酸化水素濃度'}のグラフ"><title>${rate?'平均濃度と平均減少速度':'過酸化水素濃度の時間変化'}</title>`;
 for(let i=0;i<=4;i++){let v=ymin+(ymax-ymin)*i/4,yy=y(v);svg+=`<line x1="${L}" x2="${W-RR}" y1="${yy}" y2="${yy}" stroke="#e6ede7"/><text x="${L-12}" y="${yy+4}" text-anchor="end" fill="#798f86" font-size="11">${label(v)}</text>`;let vx=xmin+(xmax-xmin)*i/4;svg+=`<text x="${x(vx)}" y="${H-18}" text-anchor="middle" fill="#798f86" font-size="11">${label(vx)}</text>`;}
 svg+=`<text x="${L}" y="12" fill="#658176" font-size="10">${rate?'平均減少速度（mol/(L·s)）':'H₂O₂（mol/L）'}</text><text x="${W-RR}" y="${H-1}" fill="#658176" font-size="10" text-anchor="end">${rate?'平均濃度（mol/L）':'時間（s）'}</text>`;
 if(!rate)svg+=`<path d="M${x(p[0][0])},${y(0)} L${p.map(([a,b])=>x(a)+','+y(b)).join(' L')} L${x(p.at(-1)[0])},${y(0)} Z" fill="#e8f4ec"/><polyline points="${p.map(([a,b])=>x(a)+','+y(b)).join(' ')}" fill="none" stroke="#16897e" stroke-width="2.5"/>`;
 if(rate&&result.fit){let sorted=p.map(r=>r[0]).sort((a,b)=>a-b),a=sorted[0],b=sorted.at(-1),k=result.fit.k,inter=result.fit.b-k*result.c0;svg+=`<line x1="${x(a)}" y1="${y(k*a+inter)}" x2="${x(b)}" y2="${y(k*b+inter)}" stroke="#9aada3" stroke-dasharray="5 5"/>`;}
 p.forEach(([a,b])=>svg+=`<circle cx="${x(a)}" cy="${y(b)}" r="4" fill="#087e79" stroke="white" stroke-width="2"><title>${a.toPrecision(5)}, ${b.toPrecision(5)}</title></circle>`);$('plot').innerHTML=svg+'</svg>';}
ids.forEach(id=>$(id).addEventListener('input',()=>{state.sample=false;update();}));
$('add').onclick=()=>{state.rows.push({time:'',vol:''});renderRows();update();};
$('sample').onclick=()=>{if(state.rows.some((r,i)=>i===0?Number(r.vol)!==0:r.time!==''||r.vol!=='' )&&!confirm('現在の測定記録を練習データに置き換えますか？'))return;Object.entries({mode:'estimate',pressure:'101300',v1:'1',v2:'1',input:'total',unit:'min',temp:'25'}).forEach(([k,v])=>$(k).value=v);$('wet').checked=true;let factor=(101300-Chem.vapor(25))*1e-6/(8.31*298.15);state.rows=[{time:0,vol:0},...Array.from({length:8},(_,i)=>{let t=(i+1)*2,n=.8*(1-Math.exp(-.0015*t*60))*.002/2;return{time:t,vol:(n/factor).toFixed(3)};})];state.sample=true;renderRows();update();};
$('reset').onclick=()=>{if(!confirm('この端末の測定記録と実験条件を初期化しますか？'))return;state={rows:initialRows(),sample:false};Object.entries({mode:'estimate',c0:'',pressure:'101300',v1:'1',v2:'1',input:'total',unit:'min',temp:'25'}).forEach(([k,v])=>$(k).value=v);$('wet').checked=true;renderRows();update();};
document.querySelectorAll('[data-plot]').forEach(b=>b.onclick=()=>{plotType=b.dataset.plot;document.querySelectorAll('[data-plot]').forEach(btn=>btn.classList.toggle('active',btn===b));draw();});
$('csv').onclick=()=>{if(!result?.data.length){alert('有効な測定記録を入力してください。');return;}let c=settings(),lines=[['過酸化水素の分解速度ラボ'],['データ',state.sample?'練習用の架空データ':'測定記録'],['初濃度の方法',c.mode==='known'?'既知値':'一次反応の回帰から推定'],['初濃度 mol/L',result.c0??'推定不可'],['大気圧 Pa',c.pressure],['反応液全体積 mL',c.volume],['測定温度 ℃',c.temp],['水蒸気補正',c.wet?'あり':'なし'],['記録方式',c.input==='total'?'累積体積':'区間体積'],['k s^-1',result.fit?.k??''],[],['時間 s','入力体積 mL','区間酸素体積 mL','累積酸素体積 mL','累積酸素量 mol','濃度減少 mol/L','H2O2濃度 mol/L','区間平均濃度 mol/L','平均減少速度 mol/(L s)'],...result.data.map(r=>[r.t,r.reading,r.v,r.total,r.n,r.d,r.c??'',r.avg??'',r.rate??''])];let csv='\ufeff'+lines.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='過酸化水素_測定解析.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
try{let old=JSON.parse(localStorage.getItem(key));if(old&&Array.isArray(old.rows)&&old.rows.every(r=>r&&['time','vol'].every(k=>['string','number'].includes(typeof r[k])))){state={rows:old.rows.map(({time,vol})=>({time,vol})),sample:!!old.sample};ids.forEach(id=>{if(old.config&&old.config[id]!==undefined){if(id==='wet')$(id).checked=!!old.config[id];else $(id).value=old.config[id];}});}}catch{}
if(!state.rows.length||Number(state.rows[0].time)!==0||state.rows[0].time==='')state.rows.unshift({time:0,vol:0});
while(state.rows.length<6)state.rows.push({time:'',vol:''});
renderRows();update();
